def trap(height):
    lo, hi = 0, len(height) - 1
    left = right = water = 0
    while lo < hi:
        if height[lo] < height[hi]:
            left = max(left, height[lo])
            water += left - height[lo]
            lo += 1
        else:
            right = max(right, height[hi])
            water += right - height[hi]
            hi -= 1
    return water
